mapper.select:
/* 보유 포인트 조회 */
SELECT HLD_PNT
  FROM MBR
 WHERE MBR_SN = #{mbrSn}

mapper.update:
/* 보유 포인트 증감(잔액이 음수가 되면 0행) */
UPDATE MBR
   SET HLD_PNT = HLD_PNT + #{delta}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND HLD_PNT + #{delta} >= 0

mapper.select:
/* 멱등 요청 ID 원장 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM PNT_GNLGR
        WHERE IDMPT_DMND_ID = #{idmptDmndId}
       )

mapper.insert:
/* 포인트 원장 등록 */
INSERT INTO PNT_GNLGR
     ( MBR_SN
     , DAY_MSN_SN
     , HLD_ITEM_SN
     , PNT_DLNG_TYPE_CD
     , DLNG_PNT
     , DLNG_AFTR_BLNC_PNT
     , MEMO_CN
     , IDMPT_DMND_ID
     , REG_DT
     )
VALUES
     ( #{mbrSn}
     , #{dayMsnSn}
     , #{hldItemSn}
     , #{pntDlngTypeCd}
     , #{dlngPnt}
     , #{dlngAftrBlncPnt}
     , #{memoCn}
     , #{idmptDmndId}
     , NOW()
     )

mapper.select:
/* 기간 적립·사용 합계 조회 */
SELECT COALESCE(SUM(CASE WHEN DLNG_PNT > 0 THEN DLNG_PNT END), 0) AS EARN_PNT
     , COUNT(CASE WHEN DLNG_PNT > 0 THEN 1 END)                  AS EARN_CNT
     , COALESCE(SUM(CASE WHEN DLNG_PNT < 0 THEN DLNG_PNT END), 0) AS USE_PNT
     , COUNT(CASE WHEN DLNG_PNT < 0 THEN 1 END)                  AS USE_CNT
  FROM PNT_GNLGR
 WHERE MBR_SN = #{mbrSn}
   AND REG_DT >= #{fromDt}
   AND REG_DT < #{toDt}

/* 반려동물의 주양육자 조회 */
SELECT R.MBR_SN
  FROM BRUP_REL R
  JOIN PET P
    ON P.PET_SN = R.PET_SN
   AND P.DEL_YN = 'N'
 WHERE R.PET_SN = #{petSn}
   AND R.BRUP_ROLE_CD = #{primaryRoleCd}
   AND R.USE_YN = 'Y'
